import csv
import io


def parse_csv(raw_csv: str):
    columns = ["nct_id", "outcome_text", "assigned_type", "reading", "agree"]
    width = len(columns)
    stream = io.StringIO(raw_csv.removeprefix("\ufeff"), newline="")

    # Find the single-line header without interpreting preamble text as CSV.
    for line in stream:
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        try:
            candidate = next(csv.reader([line], delimiter=",", quotechar='"', strict=True))
        except csv.Error:
            continue
        if [field.strip() for field in candidate] == columns:
            break
    else:
        raise ValueError("Expected CSV header was not found")

    rows = []
    for row in csv.reader(stream, delimiter=",", quotechar='"', doublequote=True):
        if len(row) > width:
            # Restore unquoted commas in the free-text field, keeping the
            # identifier and the three trailing fields in their own columns.
            row = [row[0], ",".join(row[1:-3]), *row[-3:]]
        elif len(row) < width:
            row.extend([""] * (width - len(row)))
        rows.append(row)

    return {"columns": columns, "rows": rows}
